const fs=require('fs'),cp=require('child_process');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB;
const sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
assert(sh('git rev-parse HEAD')===SHA,'wrong SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');const src=fs.readFileSync(TARGET,'utf8'),p=parse(src);assert(p.declarations.length===912&&p.dead.length===192,'baseline drift');const fin=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(fin&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line))lines.splice(d.line-1,1);fs.writeFileSync(TARGET,lines.join('\n')+(fin?'\n':''));const a=parse(fs.readFileSync(TARGET,'utf8'));assert(a.declarations.length===720&&a.dead.length===0,'candidate drift');assert(sh(`git diff --numstat -- ${TARGET}`).startsWith('0\t192\t'),'numstat drift');console.log('AUTHORITY DOC CANDIDATE PASS|decl=912->720|dead=192->0|additions=0|deletions=192');